output:
cat > hex_jump.yara << 'EOF'
rule HexJump {
  strings:
    $hex = { 48 8B [0-5] 48 8B }
  condition:
    $hex
}
EOF

cat > offset_range.yara << 'EOF'
rule OffsetRange {
  strings:
    $s = "critical"
  condition:
    @s > 0x100 and @s < 0x200
}
EOF

cat > hex_wild.yara << 'EOF'
rule HexWild {
  strings:
    $hex = { E8 ?? ?? ?? ?? 90 }
  condition:
    $hex
}
EOF
